const q = $('Webhook aprobación').first().json.query || {};
const fila = $input.all().map(function (x) { return x.json; }).find(function (r) { return r && r.id === q.id; }) || null;
// Candado: la ejecución que toma la solicitud deja nota_staff = "procesando:<ejecución>:<epoch ms>".
// Si hay uno de menos de 2 minutos, otra pestaña la está procesando. Uno más viejo se ignora (ejecución caída).
const m = fila ? String(fila.nota_staff || '').match(/^procesando:([^:]+):(\d+)$/) : null;
const enProceso = !!m && (Date.now() - Number(m[2])) < 2 * 60 * 1000;
const ok = !!fila && fila.estado === 'pendiente_aprobacion' && !enProceso && (q.d === 'aprobar' || q.d === 'rechazar');
return [{ json: { valido: ok, en_proceso: enProceso, decision: q.d, id: q.id, fila: fila, lock: 'procesando:' + $execution.id + ':' + Date.now() } }];

// Diseño B: el pendiente no bloquea el horario. Al aprobar se revalida:
// si la fecha ya pasó o alguien tomó el horario, se rechaza solo.
const v = $('Validar').first().json;
const b1 = $input.first().json;
const cfg = b1.cfg || {};
const tz = cfg.zona_horaria || 'America/Montevideo';
const dur = parseInt(cfg.duracion_min || '60');
const hh = String(v.fila.hora).slice(0, 5);
const ini = DateTime.fromISO(String(v.fila.fecha) + 'T' + hh, { zone: tz });
let motivo = null;
if (!ini.isValid || ini < DateTime.now().setZone(tz)) motivo = 'fecha_pasada';
else if (!(b1.slots_libres || []).includes(hh)) motivo = 'horario_ocupado';
return [{ json: { libre: motivo === null, motivo: motivo, id: v.id, fila: v.fila, inicio: ini.toISO(), fin: ini.plus({ minutes: dur }).toISO() } }];

// Arma una página simple para el navegador de quien aprueba, con el mensaje del paso anterior.
const msg = String($json.mensaje || 'Listo.');
const esc = function (s) { return String(s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
// Título e ícono según por dónde terminó el flujo.
const finales = [
  ['Fin: aprobada', '✅', 'Visita aprobada'],
  ['Fin: rechazada', '🛑', 'Visita rechazada'],
  ['Fin: rechazo automático', '⚠️', 'No se pudo aprobar'],
  ['Solicitud en proceso', '⏳', 'Ya se está procesando'],
  ['Solicitud inválida', 'ℹ️', 'No hay nada para hacer']
];
let icono = 'ℹ️', titulo = 'Brújula';
for (const f of finales) {
  let paso = false;
  try { paso = $(f[0]).isExecuted; } catch (e) { paso = false; }
  if (paso) { icono = f[1]; titulo = f[2]; break; }
}
const estilos = 'body{margin:0;padding:32px 16px;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;background:#f4f5f7;color:#1f2328}' +
  'main{max-width:460px;margin:0 auto;background:#fff;border:1px solid #d8dde3;border-radius:14px;padding:28px;text-align:center}' +
  '.i{font-size:40px;line-height:1}h1{font-size:20px;margin:12px 0 8px}p{margin:0;color:#4a5560;line-height:1.5}small{display:block;margin-top:20px;color:#8a949e}' +
  '@media (prefers-color-scheme:dark){body{background:#16181b;color:#e8eaed}main{background:#202327;border-color:#33373c}p{color:#b6bcc3}}';
const html = '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">' +
  '<title>' + esc(titulo) + ' · Brújula</title><style>' + estilos + '</style></head><body><main>' +
  '<div class="i">' + icono + '</div><h1>' + esc(titulo) + '</h1><p>' + esc(msg) + '</p>' +
  '<small>Brújula · Laboratorio de Innovación Educativa</small></main></body></html>';
return [{ json: { html: html, titulo: titulo, mensaje: msg } }];
